package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Set;
import java.util.TreeSet;
import net.officefloor.hq.app.holiday.BusinessDays;

/** A claim by a person on a sheet: an amount (negative only for a correction, which names the number of the
 * settled claim it corrects), a date, a note (may be empty)
 * a status (DRAFT to start), a number (given when opened), who opened it, a due-by (fixed when created) and a due (fixed when settled). */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(nullable = false, precision = 19, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(nullable = false)
    private String note;

    @Column(nullable = false)
    private String status = ClaimStatus.DRAFT.name();

    /** The number given when the claim was opened (the sheet's next, or the next in its period: P1-1, X-1); null for a
     *  claim never opened; a voided claim keeps it. */
    @Column(name = "claim_number")
    private String number;

    /** The due fixed when the claim was settled; null while it is not settled or its grade had no rate then. */
    @Column(precision = 19, scale = 2)
    private BigDecimal due;

    /** The signed-in name that opened the claim; null while it was never opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** The signed-in name that last edited the claim (its form or its amount entry); null while it was never edited. */
    @Column(name = "edited_by")
    private String editedBy;

    /** The number of the bulk settle batch that settled it (or left it PENDING); null when settled one at a time. */
    @Column(name = "settle_batch")
    private Integer settleBatch;

    /** Whether the claim is bound by its person's last statement to the figure it had then. */
    @Column(nullable = false)
    private boolean stated;

    /** The figure the claim was bound to by its person's last statement; null while unbound or when it had none (n/a). */
    @Column(name = "stated_due", precision = 19, scale = 2)
    private BigDecimal statedDue;

    /** The claim's due-by: the due-terms-th business day after its due-from, skipping weekends and the sheet's
     *  holidays now on its list; worked out again whenever the holidays change. */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The date its due-by counts from, fixed when it was created (its date then). It does not change when its date
     *  changes later. */
    @Column(name = "due_from", nullable = false)
    private LocalDate dueFrom;

    /** The terms its due-by was fixed with when it was created: its person's own, else their grade's in force on its
     *  date, else the sheet's. It does not change when the terms change later. */
    @Column(name = "due_terms", nullable = false)
    private int dueTerms;

    /** The number of the settled claim of the same person this correction corrects; null for any other claim. */
    @Column(name = "corrects")
    private String corrects;

    /** The date of the claim this correction corrects (it rounds by that date); null for any other claim. */
    @Column(name = "corrects_date")
    private LocalDate correctsDate;

    /** Where the claim is listed under its person: newest first by this key. The store gives a new claim the next
     *  key, and a moved claim the next again (it is listed as its new person's newest). */
    @Column(nullable = false, insertable = false, updatable = false)
    private Long listed;

    /** The date the claim is deferred until; null for a claim never deferred. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** The last sheet's today a reminder was written for the claim; null for a claim never reminded. */
    @Column(name = "reminded_on")
    private LocalDate remindedOn;

    /** How many proofs the claim has: raised by one at a time; 0 for a new claim. */
    @Column(nullable = false)
    private int proofs;

    /** The number of the claim this one was split off from; null for a claim not made by a split. */
    @Column(name = "split_from")
    private String splitFrom;

    /** The signed-in name whose open editor locks the claim for everyone else; null while no editor holds it. */
    @Column(name = "locked_by")
    private String lockedBy;

    /** Whether the claim was added while the period its due-by falls in was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** The claim's external reference, trimmed; unique on its sheet ignoring case; null for a claim with none. */
    @Column(name = "ref")
    private String ref;

    /** The claim's tags, trimmed, lower-cased, without repeats, sorted and comma separated; null for a claim with none. */
    @Column(name = "tags")
    private String tags;

    /** Every tag the claim has ever carried, sorted and comma separated; null while it never had any. */
    @Column(name = "tags_used")
    private String tagsUsed;

    /** The reason the claim was voided with, from the sheet's list; null when it was voided without one or is not VOID. */
    @Column(name = "void_reason")
    private String voidReason;

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, String corrects) {
        this.corrects = corrects;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public LocalDate getDueFrom() {
        return dueFrom;
    }

    public int getDueTerms() {
        return dueTerms;
    }

    /** Fixes the date and terms the due-by counts from, and works it out for the sheet's holidays. */
    public void fixDue(LocalDate from, int terms, Set<LocalDate> holidays) {
        this.dueFrom = from;
        this.dueTerms = terms;
        reworkDueBy(holidays);
    }

    /** Works the due-by out again for the sheet's holidays now. */
    public void reworkDueBy(Set<LocalDate> holidays) {
        this.dueBy = BusinessDays.after(dueFrom, dueTerms, holidays);
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return ClaimStatus.valueOf(status);
    }

    public void setStatus(ClaimStatus status) {
        this.status = status.name();
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    public BigDecimal getDue() {
        return due;
    }

    public void setDue(BigDecimal due) {
        this.due = due;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public String getEditedBy() {
        return editedBy;
    }

    public void setEditedBy(String editedBy) {
        this.editedBy = editedBy;
    }

    public Integer getSettleBatch() {
        return settleBatch;
    }

    public void setSettleBatch(Integer settleBatch) {
        this.settleBatch = settleBatch;
    }

    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    public LocalDate getCorrectsDate() {
        return correctsDate;
    }

    public void setCorrectsDate(LocalDate correctsDate) {
        this.correctsDate = correctsDate;
    }

    /** The date the claim's rounding goes by: a correction's is the date of the claim it corrects, else its own. */
    public LocalDate getRoundsOn() {
        return correctsDate != null ? correctsDate : date;
    }

    /** Whether the claim is a correction: it names a claim it corrects. */
    public boolean isCorrection() {
        return corrects != null;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** Whether the claim shows and totals the figure its person's last statement bound it to: it is bound and not
     *  PENDING (a PENDING claim shows its live figure, and is bound again if rejected). */
    public boolean isBound() {
        return stated && getStatus() != ClaimStatus.PENDING;
    }

    /** Binds the claim to a figure (null: n/a), or unbinds it (live again). */
    public void bind(boolean stated, BigDecimal statedDue) {
        this.stated = stated;
        this.statedDue = stated ? statedDue : null;
    }

    public Long getListed() {
        return listed;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    public void setDeferredUntil(LocalDate deferredUntil) {
        this.deferredUntil = deferredUntil;
    }

    public LocalDate getRemindedOn() {
        return remindedOn;
    }

    public void setRemindedOn(LocalDate remindedOn) {
        this.remindedOn = remindedOn;
    }

    /** Whether the claim is deferred on a day: it is OPEN and deferred until a date after that day. Until then it counts
     *  in no total, is not overdue, cannot be settled and is left unbound by a statement. */
    public boolean isDeferredOn(LocalDate today) {
        return getStatus() == ClaimStatus.OPEN && deferredUntil != null && deferredUntil.isAfter(today);
    }

    public int getProofs() {
        return proofs;
    }

    /** Raises the claim's proofs count by one. */
    public void addProof() {
        proofs++;
    }

    public String getSplitFrom() {
        return splitFrom;
    }

    public void setSplitFrom(String splitFrom) {
        this.splitFrom = splitFrom;
    }

    public String getLockedBy() {
        return lockedBy;
    }

    public void setLockedBy(String lockedBy) {
        this.lockedBy = lockedBy;
    }

    /** Whether someone other than the user holds the claim's editor open. */
    public boolean isLockedFor(String user) {
        return lockedBy != null && !lockedBy.equals(user);
    }

    /** A copy of the claim as it stood at the end of an earlier date: the status it had then, its due fixed then
     *  (null: not settled then) and its binding then. Only worked out, never saved. */
    public Claim asOf(ClaimStatus status, BigDecimal due, boolean stated, BigDecimal statedDue) {
        Claim then = new Claim(sheetId, personId, amount, date, note, corrects);
        then.id = id;
        then.status = status.name();
        then.number = number;
        then.due = due;
        then.openedBy = openedBy;
        then.editedBy = editedBy;
        then.settleBatch = settleBatch;
        then.dueBy = dueBy;
        then.dueFrom = dueFrom;
        then.dueTerms = dueTerms;
        then.correctsDate = correctsDate;
        then.listed = listed;
        then.deferredUntil = deferredUntil;
        then.remindedOn = remindedOn;
        then.proofs = proofs;
        then.splitFrom = splitFrom;
        then.lateEntry = lateEntry;
        then.ref = ref;
        then.tags = tags;
        then.tagsUsed = tagsUsed;
        then.voidReason = status == ClaimStatus.VOID ? voidReason : null;
        then.bind(stated, statedDue);
        return then;
    }

    /** A copy of the claim for a person on another sheet, as a transfer carries it: its status, dates, note, frozen
     *  due, opener and editor, deferral, proofs and tags; unbound (a statement's figure is lost), with no number (the
     *  other sheet gives it one), no reference, batch, lock or split. Not saved. */
    public Claim transferTo(String toSheetId, Long toPersonId) {
        Claim moved = new Claim(toSheetId, toPersonId, amount, date, note, null);
        moved.status = status;
        moved.due = due;
        moved.openedBy = openedBy;
        moved.editedBy = editedBy;
        moved.dueBy = dueBy;
        moved.dueFrom = dueFrom;
        moved.dueTerms = dueTerms;
        moved.correctsDate = correctsDate;
        moved.deferredUntil = deferredUntil;
        moved.remindedOn = remindedOn;
        moved.proofs = proofs;
        moved.lateEntry = lateEntry;
        moved.tags = tags;
        moved.tagsUsed = tagsUsed;
        moved.voidReason = voidReason;
        return moved;
    }

    public String getRef() {
        return ref;
    }

    public void setRef(String ref) {
        this.ref = ref;
    }

    public String getTags() {
        return tags;
    }

    /** Gives the claim its tags (null: none), adding them to every tag it has ever carried. */
    public void setTags(String tags) {
        this.tags = tags;
        TreeSet<String> used = new TreeSet<>(Tags.list(tagsUsed));
        used.addAll(Tags.list(tags));
        this.tagsUsed = used.isEmpty() ? null : String.join(",", used);
    }

    public String getTagsUsed() {
        return tagsUsed;
    }

    public boolean isLateEntry() {
        return lateEntry;
    }

    public void setLateEntry(boolean lateEntry) {
        this.lateEntry = lateEntry;
    }

    public String getVoidReason() {
        return voidReason;
    }

    public void setVoidReason(String voidReason) {
        this.voidReason = voidReason;
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderBy;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Transient;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import org.hibernate.annotations.OptimisticLock;

/** A person on a sheet: a name and a grade (A, B or C), the date they are retired from (null: not retired),
 *  and their holds over time. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(nullable = false)
    private String name;

    @Column(nullable = false)
    private String grade;

    /** Their own terms in days (null: none): a claim of theirs is due by its date plus these, ahead of their
     *  grade's terms and the sheet's. */
    private Integer terms;

    /** Set by an edit that changed their terms, for its audit record; not stored. */
    @Transient
    private boolean termsChanged;

    /** Their contact, trimmed and lower-cased (null: none); no two people on a sheet share one. */
    private String contact;

    /** Set by an edit that changed their contact, for its audit record; not stored. */
    @Transient
    private boolean contactChanged;

    /** Their tags, trimmed, lower-cased, without repeats, sorted and comma separated (null: none); the tag totals
     *  count each claim of theirs for these as well as for the claim's own. */
    private String tags;

    /** Their place in the sheet's list, lowest first (null: their id, which puts a person added later at the end). */
    private Long position;

    /** Raised on every save; an edit naming an older version is refused. */
    @Version
    @Column(nullable = false)
    private long version;

    /** Set: the person counts as retired at once, whatever the date; claims dated after it are refused. From the day
     *  it is reached (the sheet's today on or after it) their unbound OPEN and PENDING claims leave the live totals. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** Their holds, earliest from-date first: their OPEN and PENDING claims dated within one count in no live
     *  total, unless a statement binds them; their other claims still count. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    @OrderBy("fromDate ASC, toDate ASC")
    private List<PersonHold> holds = new ArrayList<>();

    /** Their past retirements, each ended by an unretire, earliest from-date first: a claim dated after the from and
     *  before the to of one is refused, as one after a retirement is. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_retirement", joinColumns = @JoinColumn(name = "person_id"))
    @OrderBy("fromDate ASC, toDate ASC")
    private List<PersonRetirement> retirements = new ArrayList<>();

    /** Their snapshots, oldest first: one per SNAPSHOT written for them. Taking one is no edit of them. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_snapshot", joinColumns = @JoinColumn(name = "person_id"))
    @OrderColumn(name = "seq")
    @OptimisticLock(excluded = true)
    private List<PersonSnapshot> snapshots = new ArrayList<>();

    /** The sheet's today when they were added (null: not recorded); a statement as of an earlier date is refused. */
    @Column(name = "added_on")
    private LocalDate addedOn;

    /** The sheet's today when they were retired (null: not recorded, or not retired). */
    @Column(name = "retired_made_on")
    private LocalDate retiredMadeOn;

    /** The sheet they were transferred from (null: they were not transferred here). */
    @Column(name = "origin_sheet")
    private String originSheet;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
    }

    public Long getId() {
        return id;
    }

    /** Their place in the sheet's list, lowest first: their position, or their id with none set. */
    public long getPlace() {
        return position != null ? position : id;
    }

    /** Swaps their place in the list with another person's. */
    public void swapPlace(Person other) {
        long mine = getPlace();
        position = other.getPlace();
        other.position = mine;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getGrade() {
        return grade;
    }

    public void setGrade(String grade) {
        this.grade = grade;
    }

    public Integer getTerms() {
        return terms;
    }

    /** Sets their terms, noting whether they differ from the terms they had. */
    public void setTerms(Integer terms) {
        termsChanged = !java.util.Objects.equals(this.terms, terms);
        this.terms = terms;
    }

    public boolean isTermsChanged() {
        return termsChanged;
    }

    public String getOriginSheet() {
        return originSheet;
    }

    public void setOriginSheet(String originSheet) {
        this.originSheet = originSheet;
    }

    public String getContact() {
        return contact;
    }

    /** Sets their contact, noting whether it differs from the one they had. */
    public void setContact(String contact) {
        contactChanged = !java.util.Objects.equals(this.contact, contact);
        this.contact = contact;
    }

    public boolean isContactChanged() {
        return contactChanged;
    }

    public String getTags() {
        return tags;
    }

    public void setTags(String tags) {
        this.tags = tags;
    }

    public long getVersion() {
        return version;
    }

    public LocalDate getAddedOn() {
        return addedOn;
    }

    public void setAddedOn(LocalDate addedOn) {
        this.addedOn = addedOn;
    }

    /** Retires them from a date, the change made on the sheet's today given. */
    public void retire(LocalDate retiredFrom, LocalDate madeOn) {
        this.retiredFrom = retiredFrom;
        this.retiredMadeOn = madeOn;
    }

    /** Unretires them on the sheet's today given: their retirement is kept as a past one, from its date to that day. */
    public void unretire(LocalDate on) {
        retirements.add(new PersonRetirement(retiredFrom, on, retiredMadeOn, on));
        this.retiredFrom = null;
        this.retiredMadeOn = null;
    }

    /** A copy of them as they stood at the end of a date: only the holds and retirement made while the sheet's
     *  today was on or before it. Only worked out, never saved. */
    public Person asOf(LocalDate date) {
        Person then = new Person(sheetId, name, grade);
        then.id = id;
        then.position = position;
        then.terms = terms;
        then.contact = contact;
        then.tags = tags;
        then.addedOn = addedOn;
        if (retiredMadeOn == null || !retiredMadeOn.isAfter(date)) {
            then.retiredFrom = retiredFrom;
            then.retiredMadeOn = retiredMadeOn;
        }
        for (PersonRetirement r : retirements) {
            if (r.madeBy(date)) {
                then.retirements.add(r);
            } else if (r.retiredBy(date)) {
                then.retiredFrom = r.getFromDate();
                then.retiredMadeOn = r.getRetireMadeOn();
            }
        }
        holds.stream().filter(h -> h.madeBy(date)).forEach(then.holds::add);
        snapshots.stream().filter(s -> !s.getTakenOn().isAfter(date)).forEach(then.snapshots::add);
        return then;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public List<PersonRetirement> getRetirements() {
        return retirements;
    }

    public List<PersonSnapshot> getSnapshots() {
        return snapshots;
    }

    /** Records their due-total on the day being left as the sheet's today moves on. */
    public void addSnapshot(PersonSnapshot snapshot) {
        snapshots.add(snapshot);
    }

    public List<PersonHold> getHolds() {
        return holds;
    }

    public void addHold(PersonHold hold) {
        holds.add(hold);
    }

    /** Whether they have any hold. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** Whether a hold of theirs covers the date. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /** Whether their retirement date is reached on the day: it is on or before it. */
    public boolean retiredBy(LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom);
    }

    /** Whether their OPEN and PENDING claims on the date leave the live totals on the day: a hold of theirs covers
     *  the date, or their retirement date is reached. */
    public boolean leftOn(LocalDate date, LocalDate today) {
        return heldOn(date) || retiredBy(today);
    }

    /** Whether a claim on this date is refused: it is after their retirement date, or after the from and before the
     *  to of a past retirement. */
    public boolean retiredOn(LocalDate date) {
        return (retiredFrom != null && date.isAfter(retiredFrom))
                || retirements.stream().anyMatch(r -> r.refuses(date));
    }
}

package net.officefloor.hq.app.sheet;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.OneToMany;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.TreeSet;
import net.officefloor.hq.app.claim.Tags;

/** A sheet, chosen by its id; everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    /** The keys of the dated settings: those that carry a figure. */
    public static final String FLOOR = "floor", LATE_PCT = "late-pct", TERMS = "terms", CLERK_LIMIT = "clerk-limit",
            CAP = "cap", PROOF_THRESHOLD = "proof-threshold", NOTE_THRESHOLD = "note-threshold";

    /** The key of the grace days: undated, a whole number of days (null: off). */
    public static final String GRACE_DAYS = "grace-days";

    /** The key of the pot: undated, an amount with two decimals (null: none). */
    public static final String POT = "pot";

    /** The key of the alert threshold: undated, an amount with two decimals (null: off). */
    public static final String ALERT_THRESHOLD = "alert-threshold";

    /** The key of the parent sheet: undated, a sheet's id (null: none). A grade with no rate in force on a date on
     *  this sheet takes the parent's, then the parent's parent's, up to three levels up. */
    public static final String PARENT = "parent";

    /** The key of the fiscal year start month: undated, a month 1 to 12 (null: 1). */
    public static final String FISCAL_START_MONTH = "fiscal-start-month";

    /** The keys of the undated dates, as the settings form names them. */
    public static final String POLICY_DATE = "policy-date", PERIOD_NUMBERING_FROM = "period-numbering-from",
            ENTRY_DATE = "entry-date";

    /** The setting key of an action's entry in the permission matrix. */
    public static String permKey(String action) {
        return "perm-" + action;
    }

    @Id
    private String id;

    /** The sheet's today: every date decision and default date uses it, never the real clock. */
    @Column(nullable = false)
    private LocalDate today;

    /** The dated settings: each setting that carries a figure — the clerk limit (a clerk settles a claim only when
     *  its due is at or below it), the floor (a claim's live due is at least it), the terms and each grade's own terms
     *  (key terms-&lt;grade&gt;; a claim is due by its date plus that many days), the late percent (an overdue claim's due
     *  gains, for each full 30 days overdue, the one in force on that boundary date of its figure), the cap (a person's due-total is at most it) and the
     *  proof threshold (a claim whose due is above the one in force on its date cannot be settled or approved
     *  without a proof) —
     *  recorded from a from-date on. */
    @OneToMany(mappedBy = "sheet", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    private List<SheetSetting> settings = new ArrayList<>();

    /** The policy date: a claim dated before it rounds half up, one on or after it half to even; null (blank) for
     *  the sheet's today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** The period numbering from: while the sheet's today is on or after it, a claim opened is numbered within its
     *  period; null (blank) for off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    /** The entry date: while it is set, the default date of a new claim in place of the sheet's today; null (blank)
     *  for off. */
    @Column(name = "entry_date")
    private LocalDate entryDate;

    /** Whether the sheet is archived: everything on it stays visible and every change is refused. */
    @Column(nullable = false)
    private boolean archived;

    /** The sheet's today when it was archived; null while it is not, or when that was not recorded. */
    @Column(name = "archived_on")
    private LocalDate archivedOn;

    /** The number of the sheet's last bulk settle batch; 0 while it has had none. Taken through ClaimRepository. */
    @Column(name = "last_settle_batch", nullable = false, insertable = false, updatable = false)
    private int lastSettleBatch;

    /** Every tag carried by a claim that has since left the sheet (sorted, comma separated; null: none), so the tag
     *  totals still list it as a tag used on the sheet. */
    @Column(name = "departed_tags")
    private String departedTags;

    /** The late percent a sheet starts at. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    /** The terms a sheet starts at. */
    public static final int DEFAULT_TERMS = 14;

    /** The floor a sheet starts at. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    protected Sheet() {
    }

    public Sheet(String id) {
        this.id = id;
        this.today = LocalDate.now(); // a new sheet starts on the real date
    }

    public String getId() {
        return id;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    /** The dated settings recorded, by key, then by from-date (one from the beginning of time first). */
    public List<SheetSetting> getSettings() {
        return settings.stream()
                .sorted(Comparator.comparing(SheetSetting::getKey)
                        .thenComparing(SheetSetting::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** Records a setting's value from a date on (null: blank), replacing the value already recorded from that date. */
    public void record(String key, LocalDate from, String value) {
        for (SheetSetting s : settings) {
            if (s.getKey().equals(key) && Objects.equals(s.getFromDate(), from)) {
                s.setValue(value);
                return;
            }
        }
        settings.add(new SheetSetting(this, key, from, value));
    }

    /** The setting recorded for a key in force on a date: the one with the latest from-date on or before it; none
     *  before every from-date. */
    private Optional<SheetSetting> settingOn(String key, LocalDate on) {
        return settings.stream()
                .filter(s -> s.getKey().equals(key))
                .filter(s -> s.getFromDate() == null || !s.getFromDate().isAfter(on))
                .max(Comparator.comparing(SheetSetting::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())));
    }

    /** The value of a setting in force on a date, as recorded (null: blank, or none recorded). */
    public String valueOn(String key, LocalDate on) {
        return settingOn(key, on).map(SheetSetting::getValue).orElse(null);
    }

    private BigDecimal amountOn(String key, LocalDate on) {
        String value = valueOn(key, on);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The clerk limit in force on the sheet's today; null when there is none. */
    public BigDecimal getClerkLimit() {
        return amountOn(CLERK_LIMIT, today);
    }

    /** The floor in force on a date; the starting 1.00 before every from-date. */
    public BigDecimal floorOn(LocalDate on) {
        BigDecimal floor = amountOn(FLOOR, on);
        return floor != null ? floor : DEFAULT_FLOOR;
    }

    /** The terms in force on a date; the starting 14 before every from-date. */
    public int termsOn(LocalDate on) {
        String terms = valueOn(TERMS, on);
        return terms != null ? Integer.parseInt(terms) : DEFAULT_TERMS;
    }

    /** The late percent in force on a date; the starting 0.00 before every from-date. */
    public BigDecimal latePctOn(LocalDate on) {
        BigDecimal latePct = amountOn(LATE_PCT, on);
        return latePct != null ? latePct : DEFAULT_LATE_PCT;
    }

    /** The grade's own terms in days in force on a date (grades A, B and C); null when it has none and uses the
     *  sheet's terms. */
    public Integer gradeTermsOn(String grade, LocalDate on) {
        String terms = valueOn(TERMS + "-" + grade, on);
        return terms != null ? Integer.valueOf(terms) : null;
    }

    /** The terms for a person on a date: their own terms when they have any, else their grade's in force then. */
    public int termsFor(Integer own, String grade, LocalDate on) {
        return own != null ? own : termsFor(grade, on);
    }

    /** The setting key of a grade's grace days (dated). */
    public static String graceKey(String grade) {
        return "grace-" + grade;
    }

    /** The grade's grace days in force on a date (grades A, B and C): an overdue claim's lateness counts from its
     *  due-by plus them; null when it has none. */
    public Integer gradeGraceOn(String grade, LocalDate on) {
        String days = grade == null ? null : valueOn(graceKey(grade), on);
        return days != null ? Integer.valueOf(days) : null;
    }

    /** The terms in force for a grade on a date: its own, else the sheet's. */
    public int termsFor(String grade, LocalDate on) {
        Integer own = grade == null ? null : gradeTermsOn(grade, on);
        return own != null ? own : termsOn(on);
    }

    /** The cap in force on the sheet's today; null when there is none. */
    public BigDecimal getCap() {
        return amountOn(CAP, today);
    }

    /** The proof threshold in force on a date; null when there is none. */
    public BigDecimal proofThresholdOn(LocalDate on) {
        return amountOn(PROOF_THRESHOLD, on);
    }

    /** The setting key of a grade's proof threshold (dated). */
    public static String proofThresholdKey(String grade) {
        return PROOF_THRESHOLD + "-" + grade;
    }

    /** The grade's own proof threshold in force on a date; null when it has none. */
    public BigDecimal gradeProofThresholdOn(String grade, LocalDate on) {
        return grade == null ? null : amountOn(proofThresholdKey(grade), on);
    }

    /** The proof threshold in force for a claim of a grade on a date: the grade's own in force then when one is
     *  set, else the sheet's; null when there is none. */
    public BigDecimal proofThresholdFor(String grade, LocalDate on) {
        BigDecimal own = gradeProofThresholdOn(grade, on);
        return own != null ? own : proofThresholdOn(on);
    }

    /** The note threshold in force on a date; null when there is none. */
    public BigDecimal noteThresholdOn(LocalDate on) {
        return amountOn(NOTE_THRESHOLD, on);
    }

    /** The permission matrix entry for an action as recorded: its comma separated roles; "" when blank (the
     *  standing rule applies). Not dated. */
    public String permOf(String action) {
        String roles = valueOn(permKey(action), today);
        return roles == null ? "" : roles;
    }

    /** Whether a role may take an action: by the roles of the action's permission matrix entry, else by the
     *  standing rule — open, settle, void and close by clerk and steward; reassign and reopen by steward. */
    public boolean allows(String action, String role) {
        String roles = permOf(action);
        if (roles.isEmpty()) {
            return "steward".equals(role) || !("reassign".equals(action) || "reopen".equals(action));
        }
        return List.of(roles.split(",")).contains(role);
    }

    /** The grace days: once the sheet's today is changed, an open period whose to-date plus them is before it is
     *  closed. Not dated; null when off. */
    public Integer getGraceDays() {
        String days = valueOn(GRACE_DAYS, today);
        return days == null ? null : Integer.valueOf(days);
    }

    /** The pot: shared out among the members of each balanced pool by their shares. Not dated; null when none. */
    public BigDecimal getPot() {
        return amountOn(POT, today);
    }

    /** The alert threshold: a person whose due-total crosses above it is alerted. Not dated; null when off. */
    public BigDecimal getAlertThreshold() {
        return amountOn(ALERT_THRESHOLD, today);
    }

    /** The month (1 to 12) a fiscal year starts in. Not dated; 1 unless set. */
    public int getFiscalStartMonth() {
        String month = valueOn(FISCAL_START_MONTH, today);
        return month == null ? 1 : Integer.parseInt(month);
    }

    /** The id of the parent sheet. Not dated; null when none. */
    public String getParent() {
        return valueOn(PARENT, today);
    }

    public String getDepartedTags() {
        return departedTags;
    }

    /** Remembers the tags a claim leaving the sheet has ever carried (stored form; null: none). */
    public void addDepartedTags(String tagsUsed) {
        TreeSet<String> all = new TreeSet<>(Tags.list(departedTags));
        all.addAll(Tags.list(tagsUsed));
        this.departedTags = all.isEmpty() ? null : String.join(",", all);
    }

    public boolean isArchived() {
        return archived;
    }

    public void setArchived(boolean archived) {
        this.archived = archived;
    }

    /** Archives the sheet, on its today. */
    public void archive() {
        this.archived = true;
        this.archivedOn = today;
    }

    /** Whether the sheet had been archived by the end of a date: it was archived while its today was on or before
     *  it (one archived before that was recorded, on any date). */
    public boolean archivedBy(LocalDate date) {
        return archived && (archivedOn == null || !archivedOn.isAfter(date));
    }

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    /** The policy date in force: the one set, else the sheet's today. */
    public LocalDate policyDateInForce() {
        return policyDate != null ? policyDate : today;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    /** Whether a claim opened now is numbered within its period: the period numbering is set and today is on or after it. */
    public boolean periodNumberingOn() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    public LocalDate getEntryDate() {
        return entryDate;
    }

    public void setEntryDate(LocalDate entryDate) {
        this.entryDate = entryDate;
    }

    /** The default date of a new claim: the entry date while it is set, else the sheet's today. */
    public LocalDate entryDateInForce() {
        return entryDate != null ? entryDate : today;
    }

    public int getLastSettleBatch() {
        return lastSettleBatch;
    }
}
