package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** A sheet's period: a name (unique on the sheet) and a from and to date, inclusive; once closed, its due-total
 *  and each person's are fixed at what they were on closing, until a steward reopens it. */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    /** Whether the period is closed: no claim whose due-by falls in it can be added, edited or change status. */
    @Column(nullable = false)
    private boolean closed;

    /** Whether the period is soft-closed: its figures are fixed as on closing, but claims whose due-by falls in it can still be
     *  added, edited and change status. A period is never both closed and soft-closed. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    /** The due-total fixed when the period was closed (or soft-closed); null while it is open. */
    /** The most OPEN or PENDING claims a person may have in the period (by due-by); null for no cap. */
    @Column(name = "open_cap")
    private Integer cap;

    @Column(name = "closed_total", precision = 19, scale = 2)
    private BigDecimal closedTotal;

    /** Each person's due-total fixed when the period was closed, by person id; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", precision = 19, scale = 2)
    private Map<Long, BigDecimal> personTotals = new HashMap<>();

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate, Integer cap) {
        this(sheetId, name, fromDate, toDate);
        this.cap = cap;
    }

    public Integer getCap() {
        return cap;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    public Map<Long, BigDecimal> getPersonTotals() {
        return personTotals;
    }

    /** Closes the period, fixing each person's due-total for it and its own, their sum. */
    public void close(Map<Long, BigDecimal> personTotals) {
        this.closed = true;
        this.softClosed = false;
        fix(personTotals);
    }

    /** Soft-closes the period, fixing each person's due-total for it and its own, their sum, as closing does. */
    public void softClose(Map<Long, BigDecimal> personTotals) {
        this.softClosed = true;
        fix(personTotals);
    }

    private void fix(Map<Long, BigDecimal> personTotals) {
        this.personTotals.clear();
        this.personTotals.putAll(personTotals);
        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
    }

    /** Reopens the period, so its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.personTotals.clear();
    }

    /** Whether a date falls in this period (inclusive). */
    public boolean contains(LocalDate date) {
        return !date.isBefore(fromDate) && !date.isAfter(toDate);
    }

    /** Whether this period's dates overlap the given ones (both inclusive). */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !fromDate.isAfter(to) && !from.isAfter(toDate);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClaimFigures;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGrade;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonGrades;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Closes the period, fixing each person's due-total for it as it is now — the dues (with any late charge, as shown now) of the claims whose due-by falls in it that counted by the status they had at the end of its last day (not a person's
 *  unbound OPEN ones dated within a hold of theirs), added up, skipping n/a, 0.00 for one with none — and its own, their sum. A soft-closed period can be closed, fixing them afresh. Refuses a period already closed, and a close by a role the sheet's permission matrix does not
 *  allow to (by the standing rule, clerk and steward may). */
public class ClosePeriod {
    public void close(@Val Period period, PeriodRepository repository, ClaimRepository claims, PersonRepository people,
            RateRepository rates, SheetRepository sheets, PersonGradeRepository grades, ClaimLogRepository log,
            RoleRepository roles, @RequestHeader(name = "X-User", required = false) String user) throws InvalidPeriodException {
        Sheet sheet = sheets.findById(period.getSheetId()).orElseGet(() -> new Sheet(period.getSheetId()));
        String role = roles.roleOf(period.getSheetId(), AuditUser.decode(user));
        if (!sheet.allows("close", role)) {
            throw new InvalidPeriodException("A " + role + " cannot close a period.");
        }
        if (period.isClosed()) {
            throw new InvalidPeriodException("The period is already closed.");
        }
        period.close(totals(period, sheet, claims, people, rates, grades, log));
        repository.saveAndFlush(period);
    }

    /** Closes the period on the sheet, fixing each person's due-total for it as it is now (see above). */
    static void fix(Period period, Sheet sheet, ClaimRepository claims, PersonRepository people, RateRepository rates,
            PersonGradeRepository grades, ClaimLogRepository log) {
        period.close(totals(period, sheet, claims, people, rates, grades, log));
    }

    /** Each person's due-total for the period as it is now (see above), by person id. */
    static Map<Long, BigDecimal> totals(Period period, Sheet sheet, ClaimRepository claims, PersonRepository people,
            RateRepository rates, PersonGradeRepository grades, ClaimLogRepository log) {
        Map<Long, Person> byId = people.findListed(period.getSheetId()).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        var sheetRates = rates.findInChain(period.getSheetId());
        Map<Long, List<PersonGrade>> dated = grades.datedOnSheet(period.getSheetId());
        Map<Long, ClaimStatus> then = log.statusesOn(period.getSheetId(), period.getToDate());
        Map<Long, BigDecimal> totals = new HashMap<>();
        byId.keySet().forEach(id -> totals.put(id, BigDecimal.ZERO.setScale(2)));
        claims.findBySheetIdOrderByIdDesc(period.getSheetId()).stream()
                .filter(c -> byId.containsKey(c.getPersonId()) && ClaimFigures.countsAsOf(c, then.get(c.getId()), byId.get(c.getPersonId()), sheet.getToday())
                        && period.contains(c.getDueBy()))
                .forEach(c -> {
                    BigDecimal due = new ClaimFigures(sheetRates, new PersonGrades(byId.get(c.getPersonId()).getGrade(),
                            dated.getOrDefault(c.getPersonId(), List.of())), sheet).due(c);
                    if (due != null) {
                        totals.merge(c.getPersonId(), due, BigDecimal::add);
                    }
                });
        totals.replaceAll((id, t) -> t.setScale(2));
        return totals;
    }
}
package net.officefloor.hq.app.period;

import java.util.Comparator;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.history.HistoryRecorder;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Once the sheet's today is changed, with grace days set, closes each open period (not a soft-closed one, whose totals stay as fixed) whose to-date plus the grace
 *  days is before the new today, in order of their to-dates, fixing its totals exactly as a close by hand would (the
 *  permission matrix governs closing by hand, not this), recording each closing with auto=yes, and keeping it in the sheet's history as of its to-date (its end). */
public class AutoClosePeriods {
    public void close(@Val Sheet sheet, PeriodRepository repository, ClaimRepository claims, PersonRepository people,
            RateRepository rates, PersonGradeRepository grades, ClaimLogRepository log, RoleRepository roles,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit,
            HistoryRecorder history) {
        Integer grace = sheet.getGraceDays();
        if (grace == null) {
            return;
        }
        String by = AuditUser.decode(user);
        var due = repository.findBySheetIdOrderByFromDateAscIdAsc(sheet.getId()).stream()
                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getToDate().plusDays(grace).isBefore(sheet.getToday()))
                .sorted(Comparator.comparing(Period::getToDate).thenComparing(Period::getId))
                .toList();
        for (Period period : due) {
            ClosePeriod.fix(period, sheet, claims, people, rates, grades, log);
            history.recordOn(period, period.getToDate());
            repository.saveAndFlush(period);
            audit.record("PERIOD_CLOSED sheet=" + sheet.getId() + " by=" + by + " period=" + period.getName()
                    + " total=" + period.getClosedTotal().toPlainString() + " auto=yes");
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
