import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/**
 * Re-settles a SETTLED claim: freezes its due again at the figure it would have today as an open claim bound by no
 * statement (today's rates, grades, floor and late charge; n/a leaves it live). Only a steward re-settles, and a claim
 * whose due-by is in a closed period, or in any other status, cannot be. Returns the due it had before, for the audit.
 */
public class ApplyResettle {
    public Resettled apply(@Val Claim claim, @Val Sheet sheet, ClaimRepository repository, PersonRepository people,
            RateRepository rates, PersonGradeRepository grades, PeriodRepository periods, RoleRepository roles,
            @RequestHeader(name = "X-User", required = false) String userHeader)
            throws ClaimStatusException, ClerkLimitException {
        String user = AuditUser.decode(userHeader);
        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
            throw new ClaimStatusException("A claim in a closed period cannot be re-settled.");
        }
        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), user))) {
            throw new ClerkLimitException("Only a steward can re-settle a claim.");
        }
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be re-settled.");
        }
        BigDecimal old = claim.getDue();
        BigDecimal due = people.findById(claim.getPersonId())
                .map(p -> new ClaimFigures(rates.findInChain(claim.getSheetId()),
                        grades.gradesOf(p), sheet).openDue(claim))
                .orElse(null);
        claim.setDue(due);
        repository.saveAndFlush(claim);
        return new Resettled(old, due);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Defers an OPEN claim until a date after the sheet's today. A claim in any other status, a date not after the sheet's
 * today, or a claim whose due-by is in a closed period is refused. Returns the date, for the audit.
 */
public class ApplyDefer {
    public LocalDate apply(@Val Claim claim, @Val Sheet sheet, ClaimRepository repository, PeriodRepository periods,
            @RequestParam(name = "until", required = false) String untilParam) throws ClaimStatusException {
        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
            throw new ClaimStatusException("A claim in a closed period cannot be deferred.");
        }
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be deferred.");
        }
        LocalDate until;
        try {
            until = LocalDate.parse(untilParam == null ? "" : untilParam.trim());
        } catch (DateTimeParseException e) {
            throw new ClaimStatusException("Not a date: " + untilParam);
        }
        if (!until.isAfter(sheet.getToday())) {
            throw new ClaimStatusException("A claim can only be deferred to a date after the sheet's today.");
        }
        claim.setDeferredUntil(until);
        repository.saveAndFlush(claim);
        return until;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Raises the claim's proofs count by one; a SETTLED or VOID claim is refused. */
public class ApplyProof {
    public void apply(@Val Claim claim, ClaimRepository repository) throws ClaimStatusException {
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot gain a proof.");
        }
        claim.addProof();
        repository.saveAndFlush(claim);
    }
}
