import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { isBound, isOverdue, lateFromOf, type Claim } from '../claims/claims';
import { settingOn, type Settings } from '../roles/roles';
import { useCurrentSheet } from '../session/session';

/** A grade's rate as the store holds it: the percent with two decimals, from a date on (YYYY-MM-DD; null
 *  when it applies from the beginning of time), through a to-date (null when it has no end), and the sheet it is set
 *  on — the sheet's own, or one up its chain of parents. */
export type Rate = { grade: string; pct: string; from: string | null; to: string | null; sheet: string };

export const ratesQueryKey = (sheetId: string) => ['sheet', sheetId, 'rates'] as const;

export const ratesPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/rates`;

/** Where a candidate rate is previewed: what it would change, saving nothing. */
export const ratesPreviewPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/rate-preview`;

/** The sheet's rates, by grade, then by from-date (a rate with none first); then those of its parent, its parent's
 *  parent, and one more up, each in the same order. */
export function useRates() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: ratesQueryKey(sheet ?? ''),
    queryFn: () => getJson<Rate[]>(ratesPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** The percent ("12.50") of a grade's rate in force on a date (YYYY-MM-DD): the one whose from-date is the
 *  latest on or before it, a rate with no from-date applying from the beginning of time — or, when no rate applies
 *  then on the sheet, or that one's to-date is before the date, the next sheet's up its chain of parents (the rates
 *  come sheet by sheet, the sheet's own first); undefined when none has one. */
export function rateOn(rates: Rate[] | undefined, grade: string, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  for (const sheet of [...new Set((rates ?? []).map((r) => r.sheet))]) {
    let found: Rate | undefined;
    for (const r of rates ?? []) {
      if (r.sheet !== sheet || r.grade !== grade || (r.from !== null && r.from > date)) continue;
      if (!found || (found.from ?? '') <= (r.from ?? '')) found = r;
    }
    if (found && (found.to == null || found.to >= date)) return found.pct;
  }
  return undefined;
}

/** Whether a claim's live figures round half up: the date it rounds by (a correction's is the date of the claim it
 *  corrects) is before the sheet's policy date (its today when blank); else they round half to even. */
export function roundsHalfUp(c: Claim, settings: Settings | undefined, today: string | undefined): boolean {
  const policy = settings?.policyDate || today;
  return policy !== undefined && (c.roundsOn ?? c.date) < policy;
}

/** A claim's figure: a settled claim's frozen due, else the figure its person's last statement bound it to (not while PENDING),
 *  else its rate figure at the rate on its date of the grade (its person's grade on its date) ("n/a" when it has none),
 *  rounded by the sheet's policy; no floor (that comes last, in {@link chargedOf}). */
export function figureOf(c: Claim, rates: Rate[] | undefined, grade: string, halfUp = false): string {
  if (c.due !== null) return c.due;
  if (isBound(c)) return c.statedDue ?? 'n/a';
  return dueOf(c.amount, rateOn(rates, grade, c.date), halfUp);
}

/** A claim's due: a settled claim's frozen due, else the greater of the sheet's floor in force on its date and its figure
 *  plus its late charge — for each full 30 days it is overdue on the sheet's today, the sheet's late percent in force on that
 *  boundary date (its due-by plus its grade's grace, plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries
 *  before it, rounded like a due, added up; a boundary at 0.00 adds
 *  nothing ("n/a" when it has no figure). A statement binds only the figure: the charge and the floor keep following the
 *  sheet. A correction takes neither floor nor late charge. */
export function chargedOf(c: Claim, rates: Rate[] | undefined, grade: string, settings: Settings | undefined,
  today: string | undefined): string {
  const halfUp = roundsHalfUp(c, settings, today);
  const figure = figureOf(c, rates, grade, halfUp);
  if (c.due !== null || c.corrects !== null || figure === 'n/a') return figure;
  const floor = settings && settingOn(settings, 'floor', c.date, '1.00');
  if (today === undefined || !isOverdue(c, today, grade, settings)) return atLeast(figure, floor);
  const dueBy = Date.parse(`${lateFromOf(c, grade, settings)}T00:00:00Z`);
  const periods = Math.floor((Date.parse(`${today}T00:00:00Z`) - dueBy) / 86_400_000 / 30);
  let charge = 0n;
  for (let k = 1; k <= periods; k++) {
    const boundary = new Date(dueBy + k * 30 * 86_400_000).toISOString().slice(0, 10);
    const pct = settingOn(settings, 'late-pct', boundary, '0.00');
    if (hundredths(pct) !== 0n) charge += hundredths(dueOf(formatCents(hundredths(figure) + charge), pct, halfUp));
  }
  return atLeast(formatCents(hundredths(figure) + charge), floor);
}

/** A due raised to the floor when below it ("n/a" stays n/a; no floor leaves it as it is). */
export function atLeast(due: string, floor: string | null | undefined): string {
  if (due === 'n/a' || floor == null || floor === '') return due;
  return hundredths(due) < hundredths(floor) ? formatCents(hundredths(floor)) : due;
}

/** A two-decimal string ("12.50") in hundredths, exactly. */
const hundredths = (s: string) => BigInt(Math.round(Number(s) * 100));

/**
 * The due on an amount: amount times the percent, divided by 100, rounded half to even (or half up, away from
 * zero) to two decimals — "n/a" when there is no percent. Computed in whole hundredths, so it is exact.
 */
export function dueOf(amount: string, pct: string | undefined, halfUp = false): string {
  if (pct === undefined) return 'n/a';
  // hundredths of the amount times hundredths of the percent = the due in millionths of a percent;
  // dividing by 10000 gives cents.
  const product = hundredths(amount) * hundredths(pct);
  const negative = product < 0n;
  const magnitude = negative ? -product : product;
  const rest = magnitude % 10000n;
  let cents = magnitude / 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n))) cents += 1n;
  return formatCents(negative ? -cents : cents);
}

/** Whole cents as a two-decimal string. */
export function formatCents(cents: bigint): string {
  const negative = cents < 0n;
  const m = negative ? -cents : cents;
  return `${negative ? '-' : ''}${m / 100n}.${(m % 100n).toString().padStart(2, '0')}`;
}

/** Adds up two-decimal amounts, skipping "n/a". */
export function sumDue(dues: string[]): string {
  return formatCents(dues.filter((d) => d !== 'n/a').reduce((n, d) => n + hundredths(d), 0n));
}

/** One two-decimal amount minus another, as a two-decimal string (a minus sign when below zero). */
export function diffDue(a: string, b: string): string {
  return formatCents(hundredths(a) - hundredths(b));
}

/** The sheet's total of people's figures, skipping "n/a": with three or more figures, the single highest and the
 *  single lowest are left out. */
export function trimmedSum(dues: string[]): string {
  const figures = dues.filter((d) => d !== 'n/a').map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const kept = figures.length >= 3 ? figures.slice(1, -1) : figures;
  return formatCents(kept.reduce((n, d) => n + d, 0n));
}
import { useQuery } from '@tanstack/react-query';
import { useNavigate } from '@tanstack/react-router';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import { settingOn, type Settings } from '../roles/roles';
import { asString, useSearchParam } from '../../url/useSearchParam';

/** A claim's status: DRAFT to start, then OPEN and SETTLED; a clerk settling one above the clerk limit leaves it
 *  PENDING, until a steward approves it (SETTLED) or rejects it (OPEN again); a DRAFT, OPEN or PENDING claim can be VOID. A DRAFT can be DELETED (it counts nowhere) and restored to DRAFT on the day it was deleted. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';

/** A claim as the store holds it: the amount with two decimals, the date (YYYY-MM-DD), the note, the status and
 *  the number given when it was opened (the sheet's next, or the next in its period: P1-1, X-1; null for a claim never opened; a voided claim keeps it) and the due fixed when it was
 *  settled (null when it has none: its due is live), and who opened it (null when never opened); whether its person's last statement binds it, and the
 *  figure it binds it to (null: n/a); the number of the settled claim of the same person it corrects (null when it is not
 *  a correction — a correction is a claim with a negative amount); the date its rounding goes by (a correction's is the
 *  date of the claim it corrects, else its own). */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  /** Who last edited it (its form or its amount entry); null when never edited. */
  editedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  roundsOn: string;
  /** Its due-by (YYYY-MM-DD): the business day its terms (fixed when it was created) count to after its date then, past the holidays now. */
  dueBy: string;
  /** Its status log, oldest first: one line per status it has had, `<STATUS> by <user> on <date> due=<due>`. */
  log: string[];
  /** The date it is deferred until (YYYY-MM-DD), or null when it was never deferred. */
  deferredUntil: string | null;
  /** How many proofs it has: raised by one at a time (not on a SETTLED or VOID claim). */
  proofs: number;
  /** The number of the claim it was split off from, or null when it was not made by a split. */
  splitFrom: string | null;
  /** Whether it was added while the period its due-by falls in was soft-closed. */
  lateEntry: boolean;
  remindedOn: string | null;
  /** Its external reference, trimmed (unique on the sheet, ignoring case), or null when it has none. */
  ref: string | null;
  /** Its tags, trimmed, lower-cased and sorted, without repeats; empty when it has none. */
  tags: string[];
  /** Every tag it has ever carried, sorted: the sheet's tags are those of all its claims. */
  tagsUsed: string[];
  /** The reason it was voided with, from the sheet's list, or null when it was voided without one (or is not VOID). */
  voidReason: string | null;
  /** Its comments, oldest first: `<user> on <date>: <text>`, dated the sheet's today when each was written. */
  comments: string[];
  /** Its lines, in the order added: `<label> <qty> x <unit>`. With lines, its amount is their quantities times unit
   *  amounts, added up. */
  lines: string[];
  /** The number of the bulk settle batch that settled it (or left it PENDING); null when settled one at a time. */
  settleBatch: number | null;
};

/** Whether a claim is open: OPEN or PENDING (it goes overdue, and a hold takes it out of the live totals). */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/** Whether a claim shows and totals the figure its person's last statement bound it to: it is bound and not PENDING
 *  (a PENDING claim shows its live figure, and is bound again if rejected). */
export const isBound = (c: Claim) => c.stated && c.status !== 'PENDING';

/** Whether a claim is deferred on the sheet's today: it is OPEN and deferred until a date after it. Until then it
 *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
export const isDeferred = (c: Claim, today: string | undefined) =>
  c.status === 'OPEN' && c.deferredUntil !== null && today !== undefined && today < c.deferredUntil;

/** Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED claims do, but not a
 *  deferred one. */
export const counts = (c: Claim, today: string | undefined) => (isOpen(c) || c.status === 'SETTLED') && !isDeferred(c, today);

/** A hold: from a date on, to a date (YYYY-MM-DD, inclusive; null: open-ended). */
export type Hold = { from: string; to: string | null };

/** Each person's holds, and the date they are retired from (null: not retired), by person id. */
export type Holds = Map<number, { holds: Hold[]; retiredFrom: string | null }>;

/** The holds and retirement dates of the people, by person id. */
export const holdsOf = (people: { id: number; holds: Hold[]; retiredFrom?: string | null }[] | undefined): Holds =>
  new Map((people ?? []).map((p) => [p.id, { holds: p.holds, retiredFrom: p.retiredFrom ?? null }]));

/** Whether the claim's person has its OPEN and PENDING claims out of the live totals on the sheet's today: a hold
 *  of theirs covers its date, or their retirement date is reached (today on or after it). */
const heldOn = (c: Claim, holds: Holds, today: string | undefined) => {
  const p = holds.get(c.personId);
  if (!p) return false;
  if (p.retiredFrom !== null && today !== undefined && p.retiredFrom <= today) return true;
  return p.holds.some((h) => h.from <= c.date && (h.to === null || c.date <= h.to));
};

/** Whether a claim counts toward the live totals: as `counts`, except its person's OPEN and PENDING claims dated
 *  within a hold of theirs, or all of them once their retirement date is reached, unless a statement binds them. */
export const countsLive = (c: Claim, holds: Holds, today: string | undefined) => counts(c, today) && !(isOpen(c) && !isBound(c) && heldOn(c, holds, today));

/** The status a claim had at the end of a day (YYYY-MM-DD), as its status log records it (each line dated the sheet's
 *  today when the change was made); null when it had not been added by then. */
export function statusOn(c: Claim, day: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of c.log ?? []) {
    const m = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=\S+$/.exec(line);
    if (m && m[2] <= day) status = m[1] as ClaimStatus;
  }
  return status;
}

/** Whether a claim counts toward a period's live totals: as `countsLive`, taking the status it had at the end of
 *  the period's last day — not at all when it had not been added by then; a hold takes out only a claim that is
 *  still OPEN or PENDING and unbound now. */
export const countsAsOf = (c: Claim, holds: Holds, today: string | undefined, end: string) => {
  const status = statusOn(c, end);
  return status !== null && counts({ ...c, status }, today) && !(isOpen(c) && !isBound(c) && heldOn(c, holds, today));
};

export const claimsQueryKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

export const claimsPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/claims`;

export const personClaimsPath = (sheetId: string, personId: number) =>
  `/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/claims`;

/** Every claim on the sheet, newest first. */
export function useClaims() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: claimsQueryKey(sheet ?? ''),
    queryFn: () => getJson<Claim[]>(claimsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** An amount ("12.50") in whole cents, so sums are exact. */
const cents = (amount: string) => Math.round(Number(amount) * 100);

/** A sum of the counted (OPEN, PENDING and SETTLED) claims' amounts, with two decimals; corrections (claims that
 *  correct another) and unbound OPEN claims dated within a hold of their person are left out. */
export function sumOf(claims: Claim[], held: Holds, today: string | undefined): string {
  return (claims.filter((c) => c.corrects === null && countsLive(c, held, today)).reduce((n, c) => n + cents(c.amount), 0) / 100).toFixed(2);
}

/** A claim's due-by (YYYY-MM-DD), fixed when it was created. */
export const dueByOf = (c: Claim): string => c.dueBy;

/** The date a claim's lateness counts from (YYYY-MM-DD): its due-by plus the grace days (setting grace-<grade>) in
 *  force on its date of its person's grade on its date (`grade`); its due-by when that grade has none. */
export function lateFromOf(c: Claim, grade: string, settings: Settings | undefined): string {
  const grace = settingOn(settings, `grace-${grade}`, c.date, '');
  if (grace === '') return dueByOf(c);
  return new Date(Date.parse(`${dueByOf(c)}T00:00:00Z`) + Number(grace) * 86_400_000).toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is OPEN or PENDING, not deferred, and its due-by plus any grace of its person's grade
 *  on its date (`grade`; see {@link lateFromOf}) is before the sheet's today. */
export const isOverdue = (c: Claim, today: string | undefined, grade: string, settings: Settings | undefined) =>
  isOpen(c) && !isDeferred(c, today) && today !== undefined && lateFromOf(c, grade, settings) < today;

/** The id of the claim whose editor is open (search param `editClaim`), or '' for none. */
export const useEditingClaim = () => useSearchParam('editClaim', asString);

/** The ids of the selected claims (search param `selectedClaims`, comma-separated), a toggle for one, and a
 *  clear. The toggle works from the URL as it is when it runs, so quick clicks in a row each keep the others'. */
export function useSelectedClaims() {
  const [ids] = useSearchParam('selectedClaims', asIds);
  const navigate = useNavigate();
  const update = (change: (ids: Set<number>) => void) =>
    void navigate({
      to: '.',
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        const set = new Set(asIds(prev.selectedClaims));
        change(set);
        if (set.size === 0) delete next.selectedClaims;
        else next.selectedClaims = [...set].join(',');
        return next;
      },
      replace: true,
    });
  return {
    selected: new Set(ids),
    toggle: (id: number, on: boolean) => update((set) => (on ? set.add(id) : set.delete(id))),
    clear: () => update((set) => set.clear()),
  };
}

const asIds = (raw: unknown): number[] =>
  raw === undefined || raw === null || raw === ''
    ? []
    : String(raw).split(',').map(Number).filter((n) => Number.isInteger(n));
import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { gradeOn, usePeople, type Person } from '../people/people';
import { countsLive, holdsOf, isBound, useClaims, type Claim } from '../claims/claims';
import { useSettings, type Settings } from '../roles/roles';
import { chargedOf, formatCents, rateOn, sumDue, trimmedSum, useRates, type Rate } from './rates';

// A person's due-total: the sum of their counted claims' dues, each already rounded (a settled claim's
// frozen due, else the figure their last statement bound it to, else its live due, at least the sheet's floor; plus
// an overdue claim's late charge; each claim at the grade they had on its date) — 0.00 with nothing that counts.
// When their grade in force on the sheet's today has no rate in force then it is n/a, unless a counted claim keeps
// a figure — settled, bound, or live at another grade they had on its date, or live
// on or before the sheet's today at a rate that has ended since: then it is the sum of the figures there are. It is at most
// the sheet's cap: above it, it shows the cap and their excess the difference (n/a is not capped). Their unbound OPEN claims dated within a hold of theirs do not count. The sheet's due-total is everyone's added up, skipping n/a and, with three or more figures, the highest and the lowest.
export function personDue(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): string {
  return capped(personFigures(person, claims, rates, today, settings), settings).due;
}

/** A person's excess: how much the sum of their figures is above the sheet's cap; 0.00 when it is not (or n/a). */
export function personExcess(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): string {
  return capped(personFigures(person, claims, rates, today, settings), settings).excess;
}

/** A sum of figures held to the sheet's cap ("" for none), and how much it was above it; n/a is not capped. */
function capped(sum: string, settings: Settings | undefined): { due: string; excess: string } {
  const cap = settings?.cap ?? '';
  if (sum === 'n/a' || cap === '' || Number(sum) <= Number(cap)) return { due: sum, excess: '0.00' };
  return { due: sumDue([cap]), excess: subtract(sum, cap) };
}

/** The difference of two two-decimal amounts, exactly. */
function subtract(a: string, b: string): string {
  const cents = (s: string) => BigInt(Math.round(Number(s) * 100));
  return formatCents(cents(a) - cents(b));
}

/** The sum of a person's figures, before the cap. */
function personFigures(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): string {
  const mine = claims.filter((c) => c.personId === person.id && countsLive(c, holdsOf([person]), today));
  const grade = gradeOn(person, today);
  const kept = (c: Claim) => c.due !== null || (isBound(c) && c.statedDue !== null)
    || (!isBound(c) && (gradeOn(person, c.date) !== grade || (today !== undefined && c.date <= today)) && chargedOf(c, rates, gradeOn(person, c.date), settings, today) !== 'n/a');
  if (rateOn(rates, grade, today) === undefined && !mine.some(kept)) {
    return 'n/a';
  }
  return sumDue(mine.map((c) => chargedOf(c, rates, gradeOn(person, c.date), settings, today)));
}

function DueHeader() {
  return <th>Due</th>;
}

function PersonDue({ person }: { person: Person }) {
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  return <td data-testid="person-due-total">{personDue(person, claims.data ?? [], rates.data, today, settings.data)}</td>;
}

function ExcessHeader() {
  return <th>Excess</th>;
}

function PersonExcess({ person }: { person: Person }) {
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  return <td data-testid="person-excess">{personExcess(person, claims.data ?? [], rates.data, today, settings.data)}</td>;
}

function DueTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  if (!user || !sheet) return null;
  const total = trimmedSum((people.data ?? []).map((p) => personDue(p, claims.data ?? [], rates.data, today, settings.data)));
  return (
    <p>
      Due in total <strong data-testid="rollup-due-total">{total}</strong>
    </p>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 15, Component: DueHeader }),
  PersonCells.fill({ order: 15, Component: PersonDue }),
  PeopleColumns.fill({ order: 15.5, Component: ExcessHeader }),
  PersonCells.fill({ order: 15.5, Component: PersonExcess }),
  HomeMain.fill({ order: 31, Component: DueTotal }),
];

